import Foundation

/// One caption track on YouTube.
public struct CaptionTrack: Equatable, Sendable {
    /// yt-dlp language key, e.g. "en", "de-DE" or "en-orig".
    public let language: String
    /// Generated by YouTube's speech recognition rather than uploaded.
    public let isAutomatic: Bool

    public init(language: String, isAutomatic: Bool) {
        self.language = language
        self.isAutomatic = isAutomatic
    }

    /// "en" for "en-orig" / "en-US".
    public var baseLanguage: String { Self.base(language) }

    public var label: String {
        "\(isAutomatic ? "YouTube auto-captions" : "YouTube captions") (\(baseLanguage))"
    }

    static func base(_ code: String) -> String {
        String(code.split(separator: "-").first ?? Substring(code)).lowercased()
    }
}

public enum CaptionPicker {
    /// Best track for a transcript in the video's spoken language:
    /// uploaded captions in that language, then the original auto-captions, then anything uploaded,
    /// then English auto-captions. Auto-translated tracks are never picked when the original exists.
    public static func pick(for metadata: VideoMetadata) -> CaptionTrack? {
        let manual = metadata.subtitleLanguages.filter { $0 != "live_chat" }
        let auto = metadata.automaticCaptionLanguages
        let original = auto.first { $0.hasSuffix("-orig") }
        let spoken = metadata.language.map(CaptionTrack.base) ?? original.map(CaptionTrack.base)

        if let spoken {
            if let exact = manual.first(where: { $0.lowercased() == spoken })
                ?? manual.first(where: { CaptionTrack.base($0) == spoken }) {
                return CaptionTrack(language: exact, isAutomatic: false)
            }
            if let orig = auto.first(where: { $0 == "\(spoken)-orig" }) ?? original {
                return CaptionTrack(language: orig, isAutomatic: true)
            }
            if let same = auto.first(where: { $0.lowercased() == spoken }) {
                return CaptionTrack(language: same, isAutomatic: true)
            }
        }
        if let first = manual.first {
            return CaptionTrack(language: first, isAutomatic: false)
        }
        if let orig = original {
            return CaptionTrack(language: orig, isAutomatic: true)
        }
        if let english = auto.first(where: { $0 == "en" }) {
            return CaptionTrack(language: english, isAutomatic: true)
        }
        return nil
    }
}

/// A line of transcript text with its start time in seconds.
public struct TranscriptLine: Equatable, Sendable {
    public let start: Double
    public let text: String

    public init(start: Double, text: String) {
        self.start = start
        self.text = text
    }
}

public enum WebVTT {
    /// Text lines from a WebVTT file. YouTube auto-captions repeat each line in the next cue
    /// (rolling captions) and carry per-word timing tags; both are removed.
    public static func lines(from vtt: String) -> [TranscriptLine] {
        let rolling = vtt.contains("<c>")
        var result: [TranscriptLine] = []
        var cueStart: Double?
        var lastEmitted: String?

        let all = vtt.components(separatedBy: .newlines).map { $0.trimmingCharacters(in: .whitespaces) }
        for (index, line) in all.enumerated() {
            if line.contains("-->") {
                cueStart = parseTimestamp(String(line.prefix { $0 != " " }))
                continue
            }
            guard let start = cueStart else { continue }  // header, NOTE and STYLE blocks
            if line.isEmpty { continue }
            // Cue identifier: the line right before a timing line.
            if index + 1 < all.count, all[index + 1].contains("-->") { continue }

            let text = clean(line)
            if text.isEmpty || isAnnotation(text) { continue }
            if rolling, text == lastEmitted { continue }
            result.append(TranscriptLine(start: start, text: text))
            lastEmitted = text
        }
        return result
    }

    /// "00:01:02.500" or "01:02.500" -> seconds.
    static func parseTimestamp(_ value: String) -> Double? {
        let parts = value.split(separator: ":")
        guard (2...3).contains(parts.count) else { return nil }
        var seconds = 0.0
        for part in parts {
            guard let number = Double(part) else { return nil }
            seconds = seconds * 60 + number
        }
        return seconds
    }

    private static let tag = try! NSRegularExpression(pattern: "<[^>]*>")

    static func clean(_ line: String) -> String {
        let range = NSRange(line.startIndex..., in: line)
        var text = tag.stringByReplacingMatches(in: line, range: range, withTemplate: "")
        for (entity, char) in ["&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": "\"", "&#39;": "'", "&nbsp;": " "] {
            text = text.replacingOccurrences(of: entity, with: char)
        }
        text = text.replacingOccurrences(of: "♪", with: "")
        return text.split(whereSeparator: \.isWhitespace).joined(separator: " ")
    }

    /// "[Music]", "[Applause]", "(laughs)": sound descriptions, not speech.
    static func isAnnotation(_ text: String) -> Bool {
        (text.hasPrefix("[") && text.hasSuffix("]")) || (text.hasPrefix("(") && text.hasSuffix(")"))
    }
}

public enum TranscriptFormatter {
    /// Joins lines into paragraphs of roughly `seconds` length, breaking after a sentence end
    /// when possible, each prefixed with its start time: "[1:02] text…".
    public static func paragraphs(_ lines: [TranscriptLine], seconds: Double = 45, timestamps: Bool = true) -> [String] {
        var paragraphs: [String] = []
        var current: [String] = []
        var paragraphStart: Double?

        func flush() {
            guard let start = paragraphStart, !current.isEmpty else { return }
            let prefix = timestamps ? "[\(Format.duration(start) ?? "0:00")] " : ""
            paragraphs.append(prefix + current.joined(separator: " "))
            current = []
            paragraphStart = nil
        }

        for line in lines {
            if paragraphStart == nil { paragraphStart = line.start }
            current.append(line.text)
            let elapsed = line.start - (paragraphStart ?? line.start)
            let endsSentence = line.text.last.map { ".!?…".contains($0) } ?? false
            if (elapsed >= seconds && endsSentence) || elapsed >= seconds * 2 {
                flush()
            }
        }
        flush()
        return paragraphs
    }

    /// The text file written next to the download.
    public static func document(title: String, url: String, source: String, paragraphs: [String]) -> String {
        ([title, url, "Transcript: \(source)", ""] + paragraphs.flatMap { [$0, ""] })
            .joined(separator: "\n")
    }
}

public enum TextChunker {
    /// Splits text into pieces of at most `maxCharacters`, preferring paragraph, then sentence,
    /// then word boundaries.
    public static func chunks(_ text: String, maxCharacters: Int) -> [String] {
        precondition(maxCharacters > 0)
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > maxCharacters else { return trimmed.isEmpty ? [] : [trimmed] }

        var pieces: [String] = []
        for paragraph in trimmed.components(separatedBy: "\n").filter({ !$0.trimmingCharacters(in: .whitespaces).isEmpty }) {
            if paragraph.count <= maxCharacters {
                pieces.append(paragraph)
            } else {
                pieces += splitLong(paragraph, maxCharacters: maxCharacters)
            }
        }

        var chunks: [String] = []
        var current = ""
        for piece in pieces {
            let candidate = current.isEmpty ? piece : current + "\n" + piece
            if candidate.count <= maxCharacters {
                current = candidate
            } else {
                if !current.isEmpty { chunks.append(current) }
                current = piece
            }
        }
        if !current.isEmpty { chunks.append(current) }
        return chunks
    }

    private static func splitLong(_ text: String, maxCharacters: Int) -> [String] {
        var sentences: [String] = []
        text.enumerateSubstrings(in: text.startIndex..., options: .bySentences) { sub, _, _, _ in
            if let sub, !sub.trimmingCharacters(in: .whitespaces).isEmpty {
                sentences.append(sub.trimmingCharacters(in: .whitespaces))
            }
        }
        var units: [String] = []
        for sentence in sentences {
            if sentence.count <= maxCharacters {
                units.append(sentence)
            } else {
                units += splitWords(sentence, maxCharacters: maxCharacters)
            }
        }
        var result: [String] = []
        var current = ""
        for unit in units {
            let candidate = current.isEmpty ? unit : current + " " + unit
            if candidate.count <= maxCharacters {
                current = candidate
            } else {
                if !current.isEmpty { result.append(current) }
                current = unit
            }
        }
        if !current.isEmpty { result.append(current) }
        return result
    }

    private static func splitWords(_ text: String, maxCharacters: Int) -> [String] {
        var result: [String] = []
        var current = ""
        for word in text.split(separator: " ") {
            var word = String(word)
            while word.count > maxCharacters {  // a single "word" longer than the limit
                if !current.isEmpty { result.append(current); current = "" }
                result.append(String(word.prefix(maxCharacters)))
                word = String(word.dropFirst(maxCharacters))
            }
            let candidate = current.isEmpty ? word : current + " " + word
            if candidate.count <= maxCharacters {
                current = candidate
            } else {
                result.append(current)
                current = word
            }
        }
        if !current.isEmpty { result.append(current) }
        return result
    }
}

/// File names written next to a download: "Title [id].m4a" -> "Title [id].transcript.txt".
public enum TextOutputs {
    public static func transcriptURL(for media: URL) -> URL {
        media.deletingPathExtension().appendingPathExtension("transcript.txt")
    }

    public static func summaryURL(for media: URL) -> URL {
        media.deletingPathExtension().appendingPathExtension("summary.md")
    }
}
